// === S3 新增白名单动作：显式改时间（reschedule 提案的执行端；与 cycle_slot 的
//   5 槽轮换互补——这里写入显式 day/part，词表归一由 plan_parse 前置保证）===
let slot_save_result = "ok"
fn set_slot(id_str, nd, np){
    if id_str == "" || id_str == "0" {
        ui.hint.set_text("先选中一条守护再改时间")
        return
    }
    let cur = -1
    for si in cases.len() {
        if "" + cases[si]["id"] == id_str { cur = si }
    }
    if cur < 0 {
        ui.hint.set_text("找不到 #" + id_str + "，请重新选中")
        return
    }
    if cases[cur]["status"] == "Cancelled" {
        ui.hint.set_text("该守护已取消，改时间无效（#" + id_str + "）")
        return
    }
    if nd == "" && np == "" {
        ui.hint.set_text("改期需要时间（星期几/时段至少其一）")
        return
    }
    // C4 重建数组（改 slot 两字段 + slot_init_asked 归零，其余原样保留）
    let new_cases = []
    for ri in cases.len() {
        if ri == cur {
            new_cases.push({"id": cases[ri]["id"], "text": cases[ri]["text"],
                "activity": cases[ri]["activity"], "place": cases[ri]["place"],
                "status": cases[ri]["status"],
                "slot_day": nd, "slot_part": np,
                "conflict": cases[ri]["conflict"], "people": cases[ri]["people"],
                "bill_total": cases[ri]["bill_total"],
                "receipt_activity": cases[ri]["receipt_activity"],
                "receipt_place": cases[ri]["receipt_place"],
                "receipt_text": cases[ri]["receipt_text"],
                "receipt_done": cases[ri]["receipt_done"],
                "slot_init_asked": ""})
        } else {
            new_cases.push({"id": cases[ri]["id"], "text": cases[ri]["text"],
                "activity": cases[ri]["activity"], "place": cases[ri]["place"],
                "status": cases[ri]["status"],
                "slot_day": cases[ri]["slot_day"], "slot_part": cases[ri]["slot_part"],
                "conflict": cases[ri]["conflict"], "people": cases[ri]["people"],
                "bill_total": cases[ri]["bill_total"],
                "receipt_activity": cases[ri]["receipt_activity"],
                "receipt_place": cases[ri]["receipt_place"],
                "receipt_text": cases[ri]["receipt_text"],
                "receipt_done": cases[ri]["receipt_done"],
                "slot_init_asked": cases[ri]["slot_init_asked"]})
        }
    }
    cases = new_cases
    mark_conflicts()
    let my_conflict = "" + cases[cur]["conflict"]
    rebuild_lines()
    // 决赛 S1：统一走 save() 咽喉
    save()
    slot_save_result = save_result
    render_views()
    if slot_save_result == "fail" {
        ui.hint.set_text("#" + id_str + " 改期 " + nd + "-" + np + "（保存失败，仅在内存）")
    } else if my_conflict == "yes" {
        ui.hint.set_text("#" + id_str + " 改期 " + nd + "-" + np + "（与另一条同时段，仍冲突）")
    } else {
        ui.hint.set_text("#" + id_str + " 改期 " + nd + "-" + np + "（已无冲突）")
    }
}

// 冲突全量重算（cycle_slot 同款逻辑抽出复用；set_slot / create_case_from_plan 共用）
fn mark_conflicts(){
    for a1 in cases.len() { if cases[a1]["status"] != "Cancelled" { cases[a1]["conflict"] = "no" } }
    for a2 in cases.len() {
        if cases[a2]["status"] == "Cancelled" { continue }
        let d2 = "" + cases[a2]["slot_day"]
        let p2 = "" + cases[a2]["slot_part"]
        if d2 == "" || p2 == "" { continue }
        for a3 in cases.len() {
            if a3 == a2 { continue }
            if cases[a3]["status"] == "Cancelled" { continue }
            let d3 = "" + cases[a3]["slot_day"]
            let p3 = "" + cases[a3]["slot_part"]
            if d3 == "" || p3 == "" { continue }
            if d3 == d2 && p3 == p2 {
                cases[a2]["conflict"] = "yes"
                cases[a3]["conflict"] = "yes"
            }
        }
    }
}

// 管家 create 提案的执行端：字段由提案给定（非本地猜测），空字段保持空（no-facts）；
// id 守卫与 build_case_from_text 同款；冲突走 mark_conflicts 全量重算
fn create_case_from_plan(){
    let max_existing_id = 0
    for i in cases.len() {
        let cid = cases[i]["id"]
        if cid > max_existing_id { max_existing_id = cid }
    }
    if seq <= max_existing_id { seq = max_existing_id + 1 }
    cases.push({"id": seq, "text": plan_src, "activity": plan_activity, "place": plan_place, "status": "Proposing", "people": plan_people, "bill_total": plan_bill, "receipt_activity": "", "receipt_place": "", "receipt_text": "", "receipt_done": "", "slot_day": plan_day, "slot_part": plan_part, "conflict": "no", "slot_init_asked": ""})
    mark_conflicts()
    selected_id = seq
    ui.msg_input.set_text("")
    rebuild_lines()
    save()
    render_views()
}

// === #37 辅助：trim24 截到 ≤24 字 + json_field 提字段 ===
fn trim24(s){
    return trim_n(s, 24)
}
fn json_field(js, key){
    // 决赛 S4b 兼容修：同 plan_parse——index_of 不在宿主方法表，split 实现。
    //   协议保证扁平全字符串字段、值内禁双引号；兼容 "key":"v" 与 "key": "v" 两种间隔。
    let kq = "\"" + key + "\":\""
    let parts = js.split(kq)
    let rest = ""
    if parts.len() >= 2 {
        rest = parts[1]
    } else {
        let kq2 = "\"" + key + "\": \""
        let parts2 = js.split(kq2)
        if parts2.len() < 2 { return "" }
        rest = parts2[1]
    }
    // 值到下一个 " 结束（值内禁双引号，协议约束）
    let ends = rest.split("\"")
    if ends.len() < 1 { return "" }
    return ends[0]
}

// === #37 publish_glance：向 glance 屏发「今晚聚会 T-X 提醒」L0卡 ===
//   人触发（仅当 status==Confirmed 且当前时刻在约定时段前 5/30/60 分钟区间内）。
//   card-host 无 glance 服务时按"已降级本地规则"友好提示；glance capability 已在
//   manifest 封闭清单（#37 三件套②）。默认不主动调，仅"发布到 glance 屏"按钮触发。
// #40 hub 现实封闭清单无 glance，本函数在 card-host 永远降级；保留以备官方实现 glance 能力后启用
fn publish_glance(){
    // 任何低频按钮都视为"放弃取消/清空/AI 等待"
    clear_cancel_pending("")
    undo_win_open = "no"
    undo_show_flag2 = "no"
    cancel_pending_flag = "no"
    clear_pending_flag = "no"
    clear_pending_deadline = 0
    if ai_pending == "yes" {
        ui.hint.set_text("AI 还在跑，等解析完再发 glance 提醒")
        return
    }
    if !host.has("glance") {
        ui.hint.set_text("本宿主无 glance 服务（card-host），无法投递 L0 卡；外环真机可跑")
        return
    }
    // 找一条 Confirmed 的守护做投递目标；按 selected_id 优先，否则取第一条 Confirmed
    let target = -1
    if selected_id > 0 {
        for qi in cases.len() {
            if cases[qi]["id"] == selected_id {
                if "" + cases[qi]["status"] == "Confirmed" {
                    target = qi
                }
                break
            }
        }
    }
    if target < 0 {
        for qi in cases.len() {
            if "" + cases[qi]["status"] == "Confirmed" {
                target = qi
                break
            }
        }
    }
    if target < 0 {
        ui.hint.set_text("暂无「已确认」守护可发 glance 提醒（先确认一条守护）")
        return
    }
    let act = "" + cases[target]["activity"]
    let sd = "" + cases[target]["slot_day"]
    let sp = "" + cases[target]["slot_part"]
    let pl = "" + cases[target]["place"]
    let summary = "聚会提醒：" + act + " · " + sd + "-" + sp + " · " + pl
    host.request("glance.publish", {
        level: "L0",
        title: "牵线 · 守护提醒",
        body: summary
    }, fn(r){
        if r.is_ok {
            ui.hint.set_text("已投递 glance 屏（" + summary + "）")
        } else {
            ui.hint.set_text("glance 投递失败（" + r.error + "），外环真机可排查")
        }
    })
}

